let settingsData=null,learningEntries=[];
function libraryError(error){const message=error?.message||'';const target=$('#workspace-error');if(target)target.textContent=message;}
async function workspaceTask(task){libraryError(null);if($('#scan-dialog-error'))$('#scan-dialog-error').textContent='';if($('#storage-error'))$('#storage-error').textContent='';try{await task();}catch(error){libraryError(error);if($('#scan-dialog')?.open)$('#scan-dialog-error').textContent=error.message;else if($('#guide-storage-dialog')?.open&&$('#storage-error'))$('#storage-error').textContent=error.message;else toast(error.message);}}
async function loadLibrary(){if(!localRuntime||!csrf)return;try{const [settings,learning]=await Promise.all([localRequest('/api/settings').then(r=>r.json()),localRequest('/api/learning').then(r=>r.json())]);settingsData=settings;learningEntries=learning.entries||[];$('#retention-days').value=settings.settings.retentionDays;$('#storage-info').textContent=`${settings.storage}. Aufträge werden ${settings.settings.retentionDays} Tage aufbewahrt.`;renderLearning();}catch(error){libraryError(error);}}
function renderLearning(){
 const host=$('#learning-list');if(!host)return;$('#workspace-view .learning-collection').classList.toggle('has-examples',Boolean(learningEntries.length));const search=$('#learning-search'),filter=$('#learning-filter'),query=search.value.trim().toLocaleLowerCase(),selected=filter.value;const types=[...new Set(learningEntries.map(entry=>entry.documentType).filter(Boolean))].sort((a,b)=>a.localeCompare(b));filter.replaceChildren(new Option('Alle Dokumenttypen',''),...types.map(type=>new Option(type,type)));filter.value=types.includes(selected)?selected:'';window.syncDocumentTypePickers?.();const matches=learningEntries.filter(entry=>{const haystack=`${entry.name} ${entry.documentType} ${entry.targetLanguage}`.toLocaleLowerCase();return (!query||haystack.includes(query))&&(!filter.value||entry.documentType===filter.value);});const filtered=query||filter.value;$('#learning-count').textContent=filtered?`${matches.length} / ${learningEntries.length}`:String(learningEntries.length);const clear=$('#learning-clear-filters');clear.hidden=!filtered;const providerName=({chatgpt:'ChatGPT',openai:'OpenAI API',anthropic:'Claude API',deepseek:'DeepSeek API'})[activeProvider]||'ChatGPT';$('#learning-provider-note').textContent=`${window.TOCRI18n?.t('Die Auswertung nutzt den ausgewählten Anbieter:')||'Die Auswertung nutzt den ausgewählten Anbieter:'} ${providerName}. ${window.TOCRI18n?.t('Beispiele werden nur nach deiner Aktion zur Stilauswertung gesendet.')||'Beispiele werden nur nach deiner Aktion zur Stilauswertung gesendet.'}`;$('#learning-ai-open').hidden=Boolean(providerReady);const rows=matches.map(entry=>{
  const card=document.createElement('article');card.className='learning-entry';const head=document.createElement('div');head.className='learning-entry-head';const title=document.createElement('div');const name=document.createElement('strong');name.dataset.noTranslate='';name.textContent=entry.name;const meta=document.createElement('small');meta.textContent=[entry.documentType,entry.targetLanguage].filter(Boolean).join(' · ');title.append(name,meta);const toggle=document.createElement('label');toggle.className='learning-active';const input=document.createElement('input');input.type='checkbox';input.checked=entry.active;input.dataset.noTranslate='';input.setAttribute('aria-label',`${entry.name} für neue Aufträge verwenden`);input.onchange=()=>void workspaceTask(async()=>{learningEntries=(await localRequest('/api/learning/update',{id:entry.id,active:input.checked}).then(r=>r.json())).entries;renderLearning();});toggle.append(input,document.createTextNode('Anwenden'));head.append(title,toggle);const details=document.createElement('details');details.className='learning-entry-details';const detailTitle=document.createElement('summary');detailTitle.textContent='Erkannter Stil';details.append(detailTitle);const rules=document.createElement('ul');for(const rule of (entry.rules||[]).slice(0,4)){const li=document.createElement('li');li.dataset.noTranslate='';li.textContent=rule;rules.append(li);}if(rules.childNodes.length)details.append(rules);else details.hidden=true;const actions=document.createElement('div');actions.className='learning-entry-actions';const preview=document.createElement('button');preview.className='text-button';preview.textContent='Muster ansehen';preview.onclick=()=>void workspaceTask(async()=>{if(card.querySelector('canvas')){card.querySelector('.learning-preview')?.remove();preview.textContent='Muster ansehen';return;}const source=await localRequest(`/api/learning/${entry.id}/source`).then(r=>r.json());const {canvas}=await sourceCanvas(source);canvas.setAttribute('role','img');canvas.dataset.noTranslate='';canvas.setAttribute('aria-label',`Vorschau: ${entry.name}`);const frame=document.createElement('div');frame.className='learning-preview';frame.append(canvas);card.append(frame);preview.textContent='Vorschau schließen';});const remove=document.createElement('button');remove.className='text-button';remove.textContent='Entfernen';remove.onclick=()=>{if(confirm('Dieses private Muster und die gespeicherte Quelldatei entfernen?'))void workspaceTask(async()=>{learningEntries=(await localRequest('/api/learning/update',{id:entry.id,remove:true}).then(r=>r.json())).entries;renderLearning();});};actions.append(preview,remove);card.append(head,details,actions);return card;
 });if(!learningEntries.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='Hier erscheinen deine hochgeladenen Übersetzungen.';rows.push(empty);}else if(!rows.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='Keine passenden Muster. Ändere Suche oder Dokumenttypfilter.';rows.push(empty);}host.replaceChildren(...rows);
}
$('#learning-search').oninput=()=>renderLearning();$('#learning-filter').onchange=()=>renderLearning();$('#learning-clear-filters').onclick=()=>{$('#learning-search').value='';$('#learning-filter').value='';renderLearning();$('#learning-search').focus({preventScroll:true});};$('#learning-ai-open').onclick=event=>window.openAISettings?.(event.currentTarget);window.addEventListener('translateocr-locale',()=>renderLearning());
$('#learning-file').onchange=event=>{const files=[...event.target.files];event.target.value='';if(!files.length)return;void workspaceTask(async()=>{const status=$('#learning-status'),button=$('#learning-upload-title');status.textContent='Muster werden ausgewertet …';button.textContent='Bitte warten …';$('#learning-file').disabled=true;try{if(!localRuntime||!csrf)throw new Error('Bitte die lokale Anwendung öffnen.');if(!$('#model')?.value)throw new Error('Verbinde zuerst über KI im Header einen Modellanbieter.');let count=0;for(const file of files){await localRequest('/api/learning/upload',{files:await documentsForRequest([file]),provider:activeProvider||'chatgpt',model:$('#model').value});count++;status.textContent=`${count} von ${files.length} Mustern ausgewertet …`;}await loadLibrary();status.textContent=files.length===1?'Muster ausgewertet und gespeichert.':`${files.length} Muster ausgewertet und gespeichert.`;}finally{button.textContent='Fertige Übersetzungen hinzufügen';$('#learning-file').disabled=false;}});};
const retentionForm=$('#retention-form'),retentionPanel=document.createElement('section'),storageError=document.createElement('p');storageError.id='storage-error';storageError.className='error';storageError.setAttribute('role','alert');$('#storage-info').after(storageError);retentionPanel.className='retention-impact';retentionPanel.hidden=true;retentionPanel.setAttribute('aria-live','polite');retentionPanel.innerHTML='<p class="retention-impact-copy"></p><div class="retention-impact-actions"><button class="secondary retention-backup" type="button">Sicherung herunterladen</button><button class="primary retention-confirm" type="button">Aufbewahrung verkürzen</button><button class="text-button retention-cancel" type="button">Abbrechen</button></div>';retentionForm.after(retentionPanel);
function saveRetention(days,confirm=false,confirmedAffectedCount=null){return workspaceTask(async()=>{settingsData=await localRequest('/api/settings',{retentionDays:days,confirm,confirmedAffectedCount}).then(r=>r.json());$('#storage-info').textContent=`${settingsData.storage}. Aufträge werden ${settingsData.settings.retentionDays} Tage aufbewahrt.`;retentionPanel.hidden=true;$('#retention-days').value=days;await pollQueue();toast('Aufbewahrungsfrist gespeichert.');});}
retentionForm.onsubmit=event=>{event.preventDefault();void workspaceTask(async()=>{const days=Number($('#retention-days').value);if(!Number.isInteger(days)||days<1||days>365)throw new Error('Bitte eine Aufbewahrungsfrist zwischen 1 und 365 Tagen wählen.');if(days>=Number(settingsData?.settings?.retentionDays||30)){await saveRetention(days);return;}const result=await localRequest(`/api/settings/retention-impact?days=${encodeURIComponent(days)}`).then(r=>r.json()),impact=result.impact;if(!impact.affectedCount){await saveRetention(days);return;}const cutoff=new Intl.DateTimeFormat(document.documentElement.lang||'de',{dateStyle:'medium'}).format(new Date(impact.cutoff));const retentionCopy='{count} gespeicherte Aufträge werden ab {date} inklusive ihrer Ergebnisse entfernt. Laufende oder gerade bearbeitete Aufträge bleiben erhalten.';retentionPanel.querySelector('.retention-impact-copy').textContent=(window.TOCRI18n?.t(retentionCopy)||retentionCopy).replace('{count}',String(impact.affectedCount)).replace('{date}',cutoff);retentionPanel.hidden=false;retentionPanel.querySelector('.retention-confirm').onclick=()=>void saveRetention(days,true,impact.affectedCount);retentionPanel.querySelector('.retention-cancel').onclick=()=>{retentionPanel.hidden=true;$('#retention-days').value=settingsData.settings.retentionDays;};retentionPanel.querySelector('.retention-backup').onclick=()=>void downloadBackup();});};
async function downloadBackup(clearPassword=false){return workspaceTask(async()=>{const response=await localRequest('/api/backup',{passphrase:$('#backup-passphrase').value});downloadBlob(await response.blob(),'foliquo-backup.enc');if(clearPassword)$('#backup-passphrase').value='';toast('Verschlüsselte Sicherung erstellt.');});}
$('#backup-download').onclick=()=>void downloadBackup(true);
$('#backup-restore').onclick=()=>void workspaceTask(async()=>{const file=$('#backup-file').files[0];if(!file)throw new Error('Bitte eine Sicherung auswählen.');if(!confirm('Die Sicherung ersetzt die aktuellen privaten Daten. Vorher eine Sicherung herunterladen. Fortfahren?'))return;await localRequest('/api/backup/restore',{data:await fileBase64(file),passphrase:$('#backup-passphrase').value,confirm:true});location.reload();});
